var ticks = 0, tickEl = document.getElementById('tick');
setInterval(function () { tickEl.textContent = ++ticks; }, 100);
document.getElementById('run').addEventListener('click', function () {
  var out = document.getElementById('out');
  try {
    var code = 'onmessage=function(e){var s=0;for(var i=1;i<=e.data;i++){s+=i}postMessage(s)}';
    var w = new Worker(URL.createObjectURL(new Blob([code], { type: 'text/javascript' })));
    out.textContent = 'Worker started...';
    w.onmessage = function (e) { out.textContent = 'Result from worker: ' + e.data; w.terminate(); };
    w.onerror = function (e) { out.textContent = 'Worker error: ' + e.message; };
    w.postMessage(300000000);
  } catch (err) {
    out.textContent = 'Workers are blocked in this sandbox: ' + err.message;
  }
});

